 document.addEventListener('change',async e=>{const t=e.target;if(!opened())return;try{if(t.dataset.useWindows){if(t.checked)useWindows.add(t.dataset.useWindows);else useWindows.delete(t.dataset.useWindows);}if(t.id==='ref-upload'||t.id==='ref-subject-upload'){if(busy)throw Error('Wait for the current operation.');const origin=ctx.dialogName(),form=subjectBuffer;if(t.id==='ref-subject-upload')readSubject();const ids=await importImages(t.files);if(ctx.dialogName()!==origin||t.id==='ref-subject-upload'&&subjectBuffer!==form)return;if(t.id==='ref-subject-upload'){subjectBuffer.assetIds.push(...ids);await subjectForm();}else await home();}if(t.id==='ref-plan-list'){planId=t.value;renderPlan();}if(t.dataset.cardWindow){const c=currentPlan().images.find(c=>c.id===t.closest('[data-card]').dataset.card);mutate(()=>{c.windowIds=t.checked?[...new Set([...(c.windowIds||[]),t.dataset.cardWindow])]:(c.windowIds||[]).filter(id=>id!==t.dataset.cardWindow);});}if(t.matches('[data-card-field]')){mutate(captureCards);if(t.dataset.cardField==='referenceIds')renderPlan();}if(t.dataset.cardSource){const c=currentPlan().images.find(c=>c.id===t.closest('[data-card]').dataset.card);const next=t.checked?[...c.referenceIds,t.dataset.cardSource]:c.referenceIds.filter(id=>id!==t.dataset.cardSource);mutate(()=>R.reorderReferences(c,next));renderPlan();}}catch(err){toast(err.message,true);if(t.dataset.cardSource)renderPlan();}});
